from research_helpers import *
M=ev('https://www.agibot.com/article/231/detail/43.html','AGIBOT February24 2026 joint launch explicitly identifies Minth as European sales agent and names A2/X2/G2/D1 series. Current navigation includes later products not automatically included in historical sales agreement.')
