X=ev('https://www.minthgroup.com/ENG/contents/113/1272.html','Official Minbot announcement identifies corporate IP character, not a commercial robot product.')
mp=[p(n,d,M,'commercial',roles=['commercial_partner'],typ='product',sector='robotics',sub=sub,territory='Europe')for n,d,sub in [('AGIBOT A2 Series','Full-sized humanoid robot family.','service_robotics'),('AGIBOT X2 Series','Compact humanoid robot family.','service_robotics'),('AGIBOT G2 Series','Industrial embodied dual-arm robot family.','industrial_robotics'),('AGIBOT D1 Series','Quadruped inspection robot family.','service_robotics')]]
B=ev('https://www.presseportal.ch/de/pm/100015434/100564444','Canopus-authored June23 2008 PRNewswire release confirms CB1400 PhaseII mucositis programme. Historical announcement does not establish ongoing development today.')
L=ev('https://www.antaranews.com/berita/106132/canopus-biopharma-perkuat-teknologi-platform-cb1400-nya-untuk-pengobatan-mucositis-dan-onkologi','Canopus-authored June2008 PRNewswire release confirms WARF license supporting CB1400 programme.')
A=ev('https://natap.org/2007/HCV/110107_02.htm','Canopus-authored2007 BusinessWire release reproduced by NATAP identifies CB5300 antiviral candidate. Planned clinical studies and food-ingredient status do not establish approved hepatitisC medicine.')
E=ev('https://www.sec.gov/Archives/edgar/data/1404356/000147793223003916/cbia_253g1.htm','Issuer2023 offering circular establishes Canopus/BlueHeavenCoffee corporate continuity and changed business model; no current biotechnology pipeline inferred.')
cp=[p('CB1400','Historical mucositis drug-development programme.',B,roles=['developer','licensee'],aliases=['CB-1400'],evidence=[B,L]),p('CB5300','Historical hepatitisC antiviral drug-development programme.',A,aliases=['CB-5300'])]
cs=[company('MINTH GROUP LTD',mp,[M,C,X],'Four explicitly named AGIBOT families linked to Minth as European commercial partner. Family variants and later additions require model-level territorial evidence. Generic battery component categories lack unique identifiers; Minbot is corporate mascot rather than verified hardware.'),company('Canopus BioPharma Incorporated',cp,[B,L,A,E],'Two historical programmes supported by issuer-authored announcements; present lifecycle unknown following corporate repurposing as BlueHeavenCoffee. CB1600/1922/2029/2030/2009 and named diagnostic products require primary-source confirmation; secondary-database discontinued labels not copied. Retail coffee/payment software not biotech products.')]
(out/'batch-0039.json').write_text(json.dumps({'companies':cs},indent=2));print(sum(len(c['products'])for c in cs))
